import AppKit
import Foundation

/// Tracks real user input while ignoring events generated by MoveIt's own injection.
final class IdleMonitor {
    private let lock = NSLock()
    private var lastUserActivity = Date()
    private var ignoringInjection = false
    private var ignoreEventsUntil = Date.distantPast
    private var globalMonitor: Any?
    private var localMonitor: Any?
    private var started = false

    var secondsSinceUserActivity: TimeInterval {
        lock.lock()
        defer { lock.unlock() }
        return Date().timeIntervalSince(lastUserActivity)
    }

    func start() {
        lock.lock()
        guard !started else {
            lock.unlock()
            return
        }
        started = true
        lastUserActivity = Date()
        lock.unlock()

        let mask: NSEvent.EventTypeMask = [
            .mouseMoved,
            .leftMouseDown,
            .rightMouseDown,
            .otherMouseDown,
            .leftMouseDragged,
            .rightMouseDragged,
            .otherMouseDragged,
            .scrollWheel,
            .keyDown,
            .keyUp,
            .flagsChanged,
            .tabletPoint,
            .gesture,
            .magnify,
            .swipe,
            .rotate,
            .smartMagnify
        ]

        globalMonitor = NSEvent.addGlobalMonitorForEvents(matching: mask) { [weak self] _ in
            self?.noteUserActivity()
        }
        localMonitor = NSEvent.addLocalMonitorForEvents(matching: mask) { [weak self] event in
            self?.noteUserActivity()
            return event
        }
    }

    func stop() {
        if let globalMonitor {
            NSEvent.removeMonitor(globalMonitor)
        }
        if let localMonitor {
            NSEvent.removeMonitor(localMonitor)
        }
        globalMonitor = nil
        localMonitor = nil

        lock.lock()
        started = false
        lock.unlock()
    }

    /// Reset the idle clock (e.g. when the user presses Start).
    func markUserActive() {
        lock.lock()
        lastUserActivity = Date()
        lock.unlock()
    }

    /// Runs a block while treating resulting input events as synthetic (ignored).
    func performIgnoringActivity(_ body: () -> Void) {
        lock.lock()
        ignoringInjection = true
        lock.unlock()

        body()

        lock.lock()
        ignoringInjection = false
        ignoreEventsUntil = Date().addingTimeInterval(0.2)
        lock.unlock()
    }

    private func noteUserActivity() {
        lock.lock()
        defer { lock.unlock() }
        if ignoringInjection { return }
        if Date() < ignoreEventsUntil { return }
        lastUserActivity = Date()
    }
}
